import type { Text } from '@codemirror/state';
import type { Tree } from '@lezer/common';

import { getTextFromRange } from './get-text.js';
import type { _NumberFormatParser } from '../../../core/hooks/useParseNumber.js';

/** All the node types included in the lezer syntax tree. */
export type FilterFieldLezerNodeType =
  | 'Filter'
  | 'FilterGroup'
  | 'FilterStatement'
  | 'FilterKey'
  | 'Identifier'
  | 'Duration'
  | 'String'
  | 'Number'
  | 'Boolean'
  | 'ComparisonOperator'
  | 'InvalidComparisonOperator'
  | 'ExistsOperator'
  | 'PositionOperator'
  | 'LikeOperator'
  | 'FilterSimpleValue'
  | 'FilterIncludesValue'
  | 'Range'
  | 'IncompleteRange'
  | 'Inclusion'
  | 'List'
  | 'IncompleteList'
  | 'LogicalOperator'
  | 'OpeningBracket'
  | 'ClosingBracket'
  | '⚠';

/**
 * Leaf nodes of the lezer syntax tree.
 * For each leaf node, a corresponding leaf node will be created in the converted tree.
 */
const lezerLeafNodes: Array<FilterFieldLezerNodeType> = [
  'Identifier',
  'Duration',
  'Number',
  'Boolean',
  'List',
  'Range',
  'LogicalOperator',
  'ComparisonOperator',
  'InvalidComparisonOperator',
  'ExistsOperator',
  'PositionOperator',
  'LikeOperator',
  'Inclusion',
  'String',
  'OpeningBracket',
  'ClosingBracket',
  'IncompleteRange',
  'IncompleteList',
  '⚠',
];

export type FilterFieldNodeType = 'Filter' | 'Group' | 'Statement';

// The type of the node how it is called in the exposed tree.
const nodeTypeOverrides: { [key in FilterFieldLezerNodeType]?: string } = {
  FilterGroup: 'Group',
  FilterStatement: 'Statement',
  FilterKey: 'Key',
  FilterSimpleValue: 'String',
  FilterIncludesValue: 'List',
  '⚠': 'Error',
  IncompleteRange: 'Error',
  IncompleteList: 'Error',
  InvalidComparisonOperator: 'Error',
};

export type FilterFieldNodeRange = { from: number; to: number };

export type FilterFieldNodeBase = {
  range: FilterFieldNodeRange;
};

export type FilterFieldGroupNode = FilterFieldNodeBase & {
  type: FilterFieldNodeType;
  children: (FilterFieldNode | undefined)[];
};

export type FilterFieldStatementNode = FilterFieldNodeBase & {
  type: 'Statement';
  key?: FilterFieldKeyNode | FilterFieldErrorNode;
  operator?: FilterFieldLeafNode;
  value?: FilterFieldLeafNode;
};

export type FilterFieldKeyNode = FilterFieldNodeBase & {
  type: 'Key';
  textValue: string;
  value: string;
};

export type FilterFieldStringNode = FilterFieldNodeBase & {
  type: 'String';
  textValue: string;
  value: string;
  isEscaped?: boolean;
  operator?: 'contains' | 'starts-with' | 'ends-with';
  like?: boolean;
};

export type FilterFieldDurationNode = FilterFieldNodeBase & {
  type: 'Duration';
  textValue: string;
  value?: number;
  unit?: 'ns' | 'ms' | 's' | 'm' | 'h' | 'd';
};

export type FilterFieldNumberNode = FilterFieldNodeBase & {
  type: 'Number';
  textValue: string;
  value: number;
};

export type FilterFieldBooleanNode = FilterFieldNodeBase & {
  type: 'Boolean';
  textValue: string;
  value: boolean;
};

export type FilterFieldListNode = FilterFieldNodeBase & {
  type: 'List';
  textValue: string;
  value: string[];
};

export type FilterFieldRangeNode = FilterFieldNodeBase & {
  type: 'Range';
  textValue: string;
  value: { from?: number; to?: number };
};

export type FilterFieldLogicalOperatorNode = FilterFieldNodeBase & {
  type: 'LogicalOperator';
  textValue: 'and' | 'AND' | 'or' | 'OR';
  value: 'and' | 'AND' | 'or' | 'OR';
};

export type FilterFieldComparisonOperatorNode = FilterFieldNodeBase & {
  type: 'ComparisonOperator';
  textValue: '=' | '!=' | '<' | '<=' | '>' | '>=';
  value: '=' | '!=' | '<' | '<=' | '>' | '>=';
};

export type FilterFieldExistsOperatorNode = FilterFieldNodeBase & {
  type: 'ExistsOperator';
  textValue: string;
  value: boolean;
};

export type FilterFieldLikeOperatorNode = FilterFieldNodeBase & {
  type: 'Like';
  textValue: '?';
  value: '?';
};

export type FilterFieldInclusionOperatorNode = FilterFieldNodeBase & {
  type: 'Inclusion';
  textValue: 'in' | 'IN';
  value: 'in' | 'IN';
};

export type FilterFieldErrorNode = FilterFieldNodeBase & {
  type: 'Error';
  textValue: string;
  value: string;
};

export type FilterFieldLeafNode =
  | FilterFieldKeyNode
  | FilterFieldStringNode
  | FilterFieldNumberNode
  | FilterFieldBooleanNode
  | FilterFieldDurationNode
  | FilterFieldListNode
  | FilterFieldRangeNode
  | FilterFieldLogicalOperatorNode
  | FilterFieldComparisonOperatorNode
  | FilterFieldExistsOperatorNode
  | FilterFieldLikeOperatorNode
  | FilterFieldInclusionOperatorNode
  | FilterFieldErrorNode;

export type FilterFieldNode =
  | FilterFieldGroupNode
  | FilterFieldStatementNode
  | FilterFieldLeafNode;

export type FilterFieldTree = FilterFieldGroupNode['children'];

let prevDoc: string;
let cachedTree: FilterFieldTree;
let cachedHasError: boolean;

/** Iterate over the parsed document and convert the lezer tree to an object. */
export function convertLezerTree(
  tree: Tree,
  numberParser: _NumberFormatParser,
  doc?: Text,
): { tree: FilterFieldTree; hasError: boolean } {
  if (!doc || doc.toString() === '') {
    return { tree: [], hasError: false };
  }

  // If the document didn't change and we already have a converted tree, we can return that.
  if (prevDoc === doc.toString() && cachedTree) {
    return { tree: cachedTree, hasError: cachedHasError };
  }

  const convertedTree: FilterFieldGroupNode = {
    type: 'Filter',
    children: [],
    range: { from: 0, to: 0 },
  };
  // The node the currently processed node will be writing to.
  let parentNode: FilterFieldNode = convertedTree;
  // The node prior to the parent node.
  let prevNode: FilterFieldNode = convertedTree;
  // The node prior to the node prior to the parent node.
  let prevPrevNode: FilterFieldNode = convertedTree;
  // An error may occur as the last node of e.g. 'FilterSimpleValue', since this is composed
  // out of multiple tokens. To be able to extract the complete erroneous value, we need to
  // store the range of the containing node.
  let nestedErrorRange: FilterFieldNodeRange | undefined;
  // The node that was a groups' parent to reset to the correct parent after closing groups.
  // Groups are nested one level deeper than standard statements and therefore need an additional helper.
  let groupParent: FilterFieldNode = convertedTree;
  // Flag to keep track of whether the syntax is valid.
  let hasError = false;

  tree.iterate({
    from: tree.topNode.from,
    to: tree.topNode.to,
    enter: (node) => {
      if (lezerLeafNodes.includes(node.name as FilterFieldLezerNodeType)) {
        // Early exit for brackets. They are only relevant for error highlighting.
        switch (node.name as FilterFieldLezerNodeType) {
          case 'OpeningBracket':
          case 'ClosingBracket':
            // Intentionally left empty.
            return;
        }

        // Even though it is a filter field leaf node, the lezer tree has another level
        // of nesting for better syntax highlighting and error detection.
        // The lezer leaf nodes should not create a new filter field node, but store
        // the information in the already existing 'parentNode' filter field leaf node.
        if (isFilterFieldLeafNode(parentNode)) {
          switch (node.name as FilterFieldLezerNodeType) {
            case 'Identifier': {
              parentNode.textValue = `${
                (parentNode as FilterFieldStringNode).operator === 'ends-with'
                  ? '*'
                  : ''
              }${getTextFromRange(node, doc)}`;
              parentNode.value = getTextFromRange(node, doc);
              parentNode.range = {
                from: node.from,
                to: node.to,
              };
              break;
            }
            case 'Number': {
              const value = getTextFromRange(node, doc);
              const parsedNumber = numberParser.parse(value);

              parentNode.textValue = value;
              parentNode.range = {
                from: node.from,
                to: node.to,
              };

              if (!isNaN(parsedNumber)) {
                parentNode.type = 'Number';
                (parentNode as FilterFieldNumberNode).value = parsedNumber;
              }
              break;
            }
            case 'Boolean': {
              parentNode.type = 'Boolean';
              parentNode.textValue = getTextFromRange(node, doc);
              parentNode.range = {
                from: node.from,
                to: node.to,
              };
              (parentNode as FilterFieldBooleanNode).value =
                parentNode.textValue === 'true' ? true : false;
              break;
            }
            case 'Duration': {
              const textValue = getTextFromRange(node, doc);
              const count = parseInt(textValue);

              const convertedNode: FilterFieldDurationNode = {
                type: 'Duration',
                textValue,
                range: {
                  from: node.from,
                  to: node.to,
                },
                value: count,
                unit: textValue.replace(
                  `${count}`,
                  '',
                ) as FilterFieldDurationNode['unit'],
              };

              // Make sure the previous node is a filter statement.
              if (isFilterFieldStatementNode(prevNode)) {
                // Override the statement's value with the range node.
                prevNode.value = convertedNode;
              }
              break;
            }
            case 'String': {
              parentNode.textValue = getTextFromRange(node, doc);
              (parentNode as FilterFieldStringNode).value = parentNode.textValue
                .slice(1, -1)
                .replace('\\"', '"');
              parentNode.range = {
                from: node.from,
                to: node.to,
              };
              (parentNode as FilterFieldStringNode).isEscaped = true;
              break;
            }
            case 'PositionOperator': {
              if (parentNode.type === 'String') {
                const { range, operator } = parentNode;
                if (operator === 'ends-with') {
                  parentNode.textValue = `${parentNode.textValue}*`;
                  parentNode.operator = 'contains';
                } else if (range?.from === undefined) {
                  parentNode.operator = 'ends-with';
                } else {
                  parentNode.textValue = `${parentNode.textValue}*`;
                  parentNode.operator = 'starts-with';
                }
              }
              break;
            }
            case 'LikeOperator': {
              if (parentNode.type === 'String') {
                parentNode.like = true;
              }
              break;
            }
            case 'List': {
              const textValue = getTextFromRange(node, doc);
              const listItems = textValue
                .slice(1, -1) // Remove brackets
                .split(',')
                .map((item) => item.trim());
              const convertedNode: FilterFieldListNode = {
                type: 'List',
                textValue,
                value: listItems,
                range: { from: node.from, to: node.to },
              };
              // Make sure the previous node is a filter statement.
              if (isFilterFieldStatementNode(prevNode)) {
                // Override the statement's value with the range node.
                prevNode.value = convertedNode;
              }
              break;
            }
            case 'Range': {
              const textValue = getTextFromRange(node, doc);
              const range = textValue
                .slice(1, -1)
                // TODO: allow uppercased TO
                .split('to')
                .map((item) => item.trim());
              const convertedNode: FilterFieldRangeNode = {
                type: 'Range',
                textValue,
                value: {
                  ...(range[0] && { from: parseFloat(range[0]) }),
                  ...(range[1] && { to: parseFloat(range[1]) }),
                },
                range: { from: node.from, to: node.to },
              };
              // Make sure the previous node is a filter statement.
              if (isFilterFieldStatementNode(prevNode)) {
                // Override the statement's value with the range node.
                prevNode.value = convertedNode;
              }
              break;
            }
            case 'IncompleteRange':
            case 'IncompleteList':
            case 'InvalidComparisonOperator': {
              const textValue = getTextFromRange(node, doc);
              parentNode.textValue = textValue;
              parentNode.value = textValue;
              parentNode.type = nodeTypeOverrides[node.name] ?? node.name;
              parentNode.range = { from: node.from, to: node.to };
              break;
            }
            case '⚠': {
              if (parentNode.type === 'Key' && node.from === node.to) {
                // If the key has an error and the length is 0, leave the node undefined in the converted tree.
                isFilterFieldStatementNode(prevNode) && delete prevNode.key;
                break;
              }

              const textValue = getTextFromRange(nestedErrorRange ?? node, doc);
              hasError = true;
              parentNode.textValue = textValue;
              parentNode.value = textValue;
              parentNode.type = nodeTypeOverrides[node.name] ?? node.name;
              parentNode.range = nestedErrorRange ?? {
                from: node.from,
                to: node.to,
              };
              break;
            }
            case 'ComparisonOperator':
              // Intentionally left empty.
              // Due to erroneous input, like 'and foo = bar', a comparison operator may be nested in an error node.
              // In this case, we don't want to add an additional node to the converted tree.
              break;
            default:
              // eslint-disable-next-line no-console
              console.error(
                `Syntax node '${node.name}' cannot be converted inside a leaf node. Please make sure to handle all nodes accordingly.`,
              );
          }
        } else {
          switch (node.name as FilterFieldLezerNodeType) {
            case 'LogicalOperator': {
              const textValue = getTextFromRange(node, doc)
                .trim()
                .toUpperCase() as FilterFieldLogicalOperatorNode['textValue'];
              const convertedNode: FilterFieldLogicalOperatorNode = {
                type: nodeTypeOverrides[node.name] ?? node.name,
                textValue,
                value: textValue,
                // Logical operators are only detected whith a leading and trailing space -> adjust range accordingly.
                range: { from: node.from + 1, to: node.to - 1 },
              };

              // Make sure the parent node is a filter field group node.
              if (isFilterFieldGroupNode(parentNode)) {
                parentNode.children.push(convertedNode);
              }
              break;
            }
            case 'ComparisonOperator':
            case 'InvalidComparisonOperator':
            case 'Inclusion': {
              const { from, to } = node;
              const lastChar = getTextFromRange(node, doc).slice(-1);
              const isSpace = lastChar === ' ';
              const textValue = getTextFromRange(
                { from, to: isSpace ? to - 1 : to },
                doc,
              );
              const convertedNode: FilterFieldLeafNode = {
                type: nodeTypeOverrides[node.name] ?? node.name,
                textValue,
                value: textValue,
                range: { from, to: isSpace ? to - 1 : to },
              };

              // Make sure the parent node is a filter field statement.
              if (isFilterFieldStatementNode(parentNode)) {
                parentNode.operator = convertedNode;
              }
              // Don't go any deeper.
              return false;
            }
            case 'ExistsOperator': {
              const convertedNode: FilterFieldLeafNode = {
                type: nodeTypeOverrides[node.name] ?? node.name,
                textValue: getTextFromRange(node, doc),
                range: { from: node.from, to: node.to },
                value: getTextFromRange(node, doc) === '= *',
              };

              // Make sure the parent node is a filter field statement.
              if (isFilterFieldStatementNode(parentNode)) {
                parentNode.operator = convertedNode;
              }
              // Don't go any deeper.
              return false;
            }
            case '⚠': {
              hasError = true;
              const textValue = getTextFromRange(node, doc);
              const convertedNode: FilterFieldErrorNode = {
                type: nodeTypeOverrides[node.name] ?? node.name,
                textValue,
                value: textValue,
                range: { from: node.from, to: node.to },
              };

              // Make sure the parent node is a filter field statement.
              if (
                !isFilterFieldStatementNode(parentNode) ||
                (convertedNode.type === 'Error' &&
                  convertedNode.textValue === '')
              ) {
                return false;
              }

              if (parentNode.key === undefined) {
                parentNode.key = convertedNode;
              } else if (parentNode.operator === undefined) {
                parentNode.operator = convertedNode;
              } else if (
                parentNode.operator &&
                parentNode.operator.type === 'Error'
              ) {
                // There may be an error node following another error node.
                // In this case, combine the error nodes into one.
                const textValue = getTextFromRange(
                  {
                    from: parentNode.operator.range.from,
                    to: node.to,
                  },
                  doc,
                );

                if (textValue !== '') {
                  const lastChar = textValue.slice(-1);
                  const isSpace = lastChar === ' ';
                  parentNode.operator.textValue = textValue.trim();
                  parentNode.operator.value = parentNode.operator.textValue;
                  parentNode.operator.range.to =
                    convertedNode.range.to - (isSpace ? 1 : 0);
                }
              } else if (parentNode.value === undefined) {
                parentNode.value = convertedNode;
              }

              // Don't go any deeper.
              return false;
            }
            // This case only happens with an incomplete range and no operator.
            // The value can be either a list or incomplete range -> ambiguous input error.
            case 'IncompleteRange': {
              const charBeforeRange = { from: node.from - 1, to: node.from };
              const charBefore = getTextFromRange(charBeforeRange, doc);
              const isSpace = charBefore === ' ';
              const missingOperatorError: FilterFieldLeafNode = {
                type: 'Error',
                textValue: isSpace ? charBefore : '',
                value: isSpace ? charBefore : '',
                range: isSpace
                  ? charBeforeRange
                  : { from: node.from, to: node.from },
              };
              const textValue = getTextFromRange(node, doc);
              const convertedNode: FilterFieldLeafNode = {
                type: 'Error',
                textValue,
                value: textValue,
                range: { from: node.from, to: node.to },
              };

              // Make sure the parent node is a filter field statement.
              if (isFilterFieldStatementNode(parentNode)) {
                parentNode.operator = missingOperatorError;
                parentNode.value = convertedNode;
              }
              hasError = true;
              break;
            }
            default:
              // eslint-disable-next-line no-console
              console.error(
                `Syntax node '${node.name}' cannot be converted inside a branch node. Please make sure to handle all nodes accordingly.`,
              );
          }
        }
        // If the 'parentNode' is not a leaf node, any matching tokens either create a
        // new tree node or leaf node that is pushed to the 'parentNode's children.
      } else {
        let convertedNode: Partial<FilterFieldNode> = {};

        switch (node.name as FilterFieldLezerNodeType) {
          case 'Filter':
            convertedNode = convertedTree;
            return;
          case 'FilterGroup':
            Object.assign<
              Partial<FilterFieldNode | FilterFieldLeafNode>,
              FilterFieldNode
            >(convertedNode, {
              type: nodeTypeOverrides[node.name] ?? node.name,
              children: [],
              range: {
                from: node.from,
                to: node.to,
              },
            });
            groupParent = parentNode;

            // Only opening and closing bracket -> empty filter group error.
            if (node.from === node.to - 2) {
              hasError = true;
              Object.assign<
                Partial<FilterFieldNode | FilterFieldLeafNode>,
                Partial<FilterFieldNode>
              >(convertedNode, {
                children: [
                  {
                    type: 'Error',
                    textValue: '',
                    value: '',
                    range: {
                      from: node.from + 1,
                      to: node.from + 1,
                    },
                  },
                ],
              });
            }

            (parentNode as FilterFieldGroupNode).children.push(
              convertedNode as FilterFieldGroupNode,
            );

            break;
          case 'FilterStatement':
            Object.assign<
              Partial<FilterFieldNode | FilterFieldLeafNode>,
              FilterFieldStatementNode
            >(convertedNode, {
              type: nodeTypeOverrides[node.name] ?? node.name,
              range: {
                from: node.from,
                to: node.to,
              },
            });
            (parentNode as FilterFieldGroupNode).children.push(
              convertedNode as FilterFieldStatementNode,
            );
            break;
          case 'FilterKey':
          case 'FilterSimpleValue':
          case 'FilterIncludesValue':
            Object.assign<
              Partial<FilterFieldNode | FilterFieldLeafNode>,
              Partial<FilterFieldLeafNode>
            >(convertedNode, {
              type: nodeTypeOverrides[node.name] ?? node.name,
              textValue: '',
              value: '',
            });
            nestedErrorRange = {
              from: node.from,
              to: node.to,
            };

            if (isFilterFieldStatementNode(parentNode)) {
              switch (node.name as FilterFieldLezerNodeType) {
                case 'FilterKey':
                  parentNode.key = convertedNode as FilterFieldKeyNode;
                  break;
                case 'FilterSimpleValue':
                case 'FilterIncludesValue':
                  parentNode.value = convertedNode as FilterFieldLeafNode;
                  break;
              }
            }
            break;
          default:
            // eslint-disable-next-line no-console
            console.error(
              `Syntax node '${node.name}' cannot be converted. Please make sure to handle all nodes accordingly.`,
            );
        }

        prevPrevNode = prevNode;
        prevNode = parentNode;
        parentNode = convertedNode as FilterFieldLeafNode;
      }
    },
    leave: (node) => {
      switch (node.name as FilterFieldLezerNodeType) {
        case 'FilterGroup':
          parentNode = groupParent;
          prevNode = prevPrevNode;
          break;
        case 'FilterStatement':
        case 'FilterKey':
        case 'FilterSimpleValue':
        case 'List':
        case 'IncompleteList':
          parentNode = prevNode;
          prevNode = prevPrevNode;
      }

      // Reset the error range when leaving any node that can contain an error.
      switch (node.name as FilterFieldLezerNodeType) {
        case 'FilterKey':
        case 'FilterSimpleValue':
        case 'FilterIncludesValue':
          nestedErrorRange = undefined;
      }
    },
  });

  prevDoc = doc.toString();
  cachedTree = convertedTree.children;
  cachedHasError = hasError;

  return { tree: cachedTree, hasError };
}

function findStatementForSuggestions(
  cursorPosition: number,
  node?: FilterFieldNode,
) {
  if (
    !node ||
    !(node.range.from <= cursorPosition && node.range.to >= cursorPosition)
  ) {
    return null;
  }
  if (node.type === 'Group') {
    if (node.range.from === node.range.to - 2) {
      // If it is an empty group it should be treated as an empty statement
      return {} as FilterFieldNode;
    }

    let newNode: FilterFieldNode | null = null;
    node.children.forEach((childNode) => {
      const temp = findStatementForSuggestions(cursorPosition, childNode);
      if (temp) {
        newNode = temp;
        return;
      }
    });

    return newNode;
  }

  if (node.type === 'Statement') {
    return node;
  }

  return null;
}

/** Get the filter statement around the given cursor position. */
export function getFilterStatementForSuggestions(
  tree: Tree,
  cursorPosition: number,
  numberParser: _NumberFormatParser,
  doc?: Text,
): FilterFieldStatementNode | undefined {
  if (!doc) {
    return;
  }

  const { tree: convertedTree } = convertLezerTree(tree, numberParser, doc);
  let statementNode;

  convertedTree.forEach((node) => {
    const temp = findStatementForSuggestions(cursorPosition, node);

    if (temp) {
      statementNode = temp;
      return;
    }
  });

  if (!statementNode || !isFilterFieldStatementNode(statementNode)) {
    return;
  }

  return statementNode;
}

function isFilterFieldGroupNode(node: unknown): node is FilterFieldGroupNode {
  return (
    typeof node === 'object' &&
    (node as FilterFieldGroupNode).children !== undefined
  );
}

function isFilterFieldStatementNode(
  node: unknown,
): node is FilterFieldStatementNode {
  return (
    typeof node === 'object' &&
    (node as FilterFieldStatementNode).type === 'Statement'
  );
}

export function isFilterFieldLeafNode(
  node: unknown,
): node is FilterFieldLeafNode {
  return (
    typeof node === 'object' &&
    (node as FilterFieldLeafNode).textValue !== undefined
  );
}
